/bin/zsh -lc "python -c 'import pandas as pd,numpy as np; from scipy.optimize import minimize; x=pd.read_csv(\"data/freshwater_fish_basins.csv\"); y=x.diversity.to_numpy(float); cols=[np.ones(len(x)),np.log(x.area),x.bio1,x.bio12/1000];
for inds in ([0,1],[0,1,2],[0,1,3],[0,1,2,3]):
 X=np.column_stack([cols[i] for i in inds]); f=lambda b: np.sum(np.exp(X@b)-y*(X@b)); j=lambda b:X.T@(np.exp(X@b)-y); r=minimize(f,np.zeros(X.shape[1]),jac=j,method=\"BFGS\"); print(inds,r.x,2*np.sum(np.where(y>0,y*np.log(y/np.exp(X@r.x)),0)-(y-np.exp(X@r.x))))'"

